mapper.select:
SELECT lp.id, zone_code, code, name, coordinate_x, coordinate_y, coordinate_z, bank, bay, level, location_type, enabled, is_occupied, is_locked, is_reserved, lock_reason, preferred_status, created_time, updated_time FROM location_point lp LEFT JOIN location_reservation_record rr ON rr.location_point_id = lp.id AND rr.fulfilled = 0 AND rr.cancelled = 0 AND rr.expired = 0 WHERE lp.enabled = 'Y' AND lp.location_type = 'STORAGE' AND lp.is_locked = 'N' AND lp.is_reserved= 'N' AND lp.is_occupied= 'N' AND rr.id IS NULL
AND lp.id NOT IN
#{id}
ORDER BY lp.level ASC, lp.bank DESC, lp.bay ASC LIMIT #{params.limit}
FOR UPDATE SKIP LOCKED
